CREATE TABLE pine_host_sessions(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES strategy_versions(id),snapshot_id TEXT NOT NULL REFERENCES snapshots(id),subscription_id TEXT NOT NULL REFERENCES market_subscriptions(id),execution TEXT NOT NULL,starting_cash REAL NOT NULL,status TEXT NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,fill_cursor INTEGER NOT NULL DEFAULT 0,result TEXT,error TEXT,adapter_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE pine_host_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,session_id TEXT NOT NULL REFERENCES pine_host_sessions(id),event_id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,market_cursor INTEGER NOT NULL,UNIQUE(session_id,event_id));
CREATE TABLE pine_host_orders(session_id TEXT NOT NULL REFERENCES pine_host_sessions(id),pine_order_id TEXT NOT NULL,local_order_id TEXT NOT NULL REFERENCES local_orders(id),intent TEXT NOT NULL,PRIMARY KEY(session_id,pine_order_id));
CREATE INDEX pine_host_events_session ON pine_host_events(session_id,seq);
